1	package search
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"net/url"
11		"strconv"
12		"strings"
13		"time"
14	)
15	
16	const apiTimeout = 30 * time.Second
17	
18	// DefaultServiceURL is the production search service URL.
19	const DefaultServiceURL = "https://entire.io"
20	
21	// WildcardQuery is the query string used when only filters are provided (no search terms).
22	const WildcardQuery = "*"
23	
24	// AllReposFilter is the inline repo filter value that disables repo scoping.
25	const AllReposFilter = "*"
26	
27	// MaxLimit is the maximum number of results the search API will return per request.
28	const MaxLimit = 200
29	
30	// Meta contains search ranking metadata for a result.
31	type Meta struct {
32		MatchType string  `json:"matchType"`
33		Score     float64 `json:"score"`
34		Snippet   string  `json:"snippet,omitempty"`
35	}
36	
37	// CheckpointResult represents a checkpoint returned by the search service.
38	type CheckpointResult struct {
39		ID             string   `json:"id"`
40		Prompt         string   `json:"prompt"`
41		CommitMessage  *string  `json:"commitMessage"`
42		CommitSHA      *string  `json:"commitSha"`
43		Branch         string   `json:"branch"`
44		Org            string   `json:"org"`
45		Repo           string   `json:"repo"`
46		Author         string   `json:"author"`
47		AuthorUsername *string  `json:"authorUsername"`
48		CreatedAt      string   `json:"createdAt"`
49		FilesTouched   []string `json:"filesTouched"`
50	}
51	
52	// Result wraps a search result with its type and ranking metadata.
53	type Result struct {
54		Type string           `json:"type"`
55		Data CheckpointResult `json:"data"`
56		Meta Meta             `json:"searchMeta"`
57	}
58	
59	// Response is the search service response.
60	type Response struct {
61		Results []Result `json:"results"`
62		Total   int      `json:"total"`
63		Page    int      `json:"page"`
64		Error   string   `json:"error,omitempty"`
65	}
66	
67	// Config holds the configuration for a search request.
68	type Config struct {
69		ServiceURL  string // Base URL of the search service
70		GitHubToken string
71		Owner       string
72		Repo        string
73		Repos       []string
74		Query       string
75		Limit       int
76		Author      string // Filter by author name
77		Date        string // Filter by time period: "week" or "month"
78		Branch      string // Filter by branch name
79		Page        int    // 1-based page number (0 means omit, API defaults to 1)
80	}
81	
82	// HasFilters reports whether any filter fields are set on the config.
83	func (c Config) HasFilters() bool {
84		return c.Author != "" || c.Date != "" || c.Branch != "" || len(c.Repos) > 0
85	}
86	
87	// ParsedInput holds the parsed query and optional filters extracted from search input.
88	type ParsedInput struct {
89		Query  string
90		Author string
91		Date   string
92		Branch string
93		Repos  []string
94	}
95	
96	// ParseSearchInput extracts filter prefixes from raw input.
97	// Supports quoted values for single-value filters, for example: author:"alice smith".
98	// Remaining tokens become the query.
99	func ParseSearchInput(raw string) ParsedInput {
100		var p ParsedInput
101		var queryParts []string
102	
103		tokens := tokenizeInput(raw)
104		for _, tok := range tokens {
105			switch {
106			case strings.HasPrefix(tok, "author:"):
107				p.Author = strings.Trim(tok[len("author:"):], "\"")
108			case strings.HasPrefix(tok, "date:"):
109				p.Date = strings.Trim(tok[len("date:"):], "\"")
110			case strings.HasPrefix(tok, "branch:"):
111				p.Branch = strings.Trim(tok[len("branch:"):], "\"")
112			case strings.HasPrefix(tok, "repo:"):
113				p.Repos = appendUnique(p.Repos, parseListFilter(strings.TrimPrefix(tok, "repo:"))...)
114			default:
115				queryParts = append(queryParts, tok)
116			}
117		}
118	
119		p.Query = strings.Join(queryParts, " ")
120		return p
121	}
122	
123	// tokenizeInput splits input on whitespace but respects quoted values after filter prefixes.
124	// Example: `author:"alice smith" fix bug` → ["author:\"alice smith\"", "fix", "bug"]
125	func tokenizeInput(s string) []string {
126		var tokens []string
127		i := 0
128		s = strings.TrimSpace(s)
129		for i < len(s) {
130			// Skip whitespace
131			for i < len(s) && s[i] == ' ' {
132				i++
133			}
134			if i >= len(s) {
135				break
136			}
137	
138			start := i
139	
140			// Look ahead: is this a prefix:"quoted" token?
141			if colonIdx := strings.Index(s[i:], ":\""); colonIdx >= 0 && !strings.Contains(s[i:i+colonIdx], " ") {
142				// Found prefix:" — scan to closing quote
143				quoteStart := i + colonIdx + 2
144				endQuote := strings.IndexByte(s[quoteStart:], '"')
145				if endQuote >= 0 {
146					i = quoteStart + endQuote + 1
147					tokens = append(tokens, s[start:i])
148					continue
149				}
150			}
151	
152			// Regular token: advance to next space
153			for i < len(s) && s[i] != ' ' {
154				i++
155			}
156			tokens = append(tokens, s[start:i])
157		}
158		return tokens
159	}
160	
161	func parseListFilter(raw string) []string {
162		if raw == "" {
163			return nil
164		}
165	
166		parts := strings.Split(raw, ",")
167		values := make([]string, 0, len(parts))
168		for _, part := range parts {
169			value := strings.Trim(strings.TrimSpace(part), "\"")
170			if value == "" {
171				continue
172			}
173			values = append(values, value)
174		}
175	
176		return values
177	}
178	
179	// ValidateRepoFilters ensures repo filters match backend semantics.
180	func ValidateRepoFilters(repos []string) error {
181		if len(repos) > 1 {
182			return errors.New("only one explicit repo filter is currently supported")
183		}
184		if len(repos) == 1 && !isValidRepoFilter(repos[0]) {
185			return fmt.Errorf(
186				"invalid repo filter %q: expected owner/name or *; if you meant all repos, quote the asterisk: --repo '*'",
187				repos[0],
188			)
189		}
190		return nil
191	}
192	
193	func isValidRepoFilter(repo string) bool {
194		if repo == AllReposFilter {
195			return true
196		}
197		if strings.Contains(repo, " ") {
198			return false
199		}
200		parts := strings.Split(repo, "/")
201		return len(parts) == 2 && parts[0] != "" && parts[1] != ""
202	}
203	
204	func appendUnique(existing []string, values ...string) []string {
205		if len(values) == 0 {
206			return existing
207		}
208	
209		seen := make(map[string]struct{}, len(existing)+len(values))
210		for _, value := range existing {
211			seen[value] = struct{}{}
212		}
213		for _, value := range values {
214			if _, ok := seen[value]; ok {
215				continue
216			}
217			seen[value] = struct{}{}
218			existing = append(existing, value)
219		}
220	
221		return existing
222	}
223	
224	var httpClient = &http.Client{}
225	
226	// Search calls the search service to perform a hybrid search.
227	func Search(ctx context.Context, cfg Config) (*Response, error) {
228		ctx, cancel := context.WithTimeout(ctx, apiTimeout)
229		defer cancel()
230	
231		serviceURL := cfg.ServiceURL
232		if serviceURL == "" {
233			serviceURL = DefaultServiceURL
234		}
235	
236		u, err := url.Parse(serviceURL)
237		if err != nil {
238			return nil, fmt.Errorf("parsing service URL: %w", err)
239		}
240		u.Path = "/search/v1/search"
241	
242		q := u.Query()
243		q.Set("q", cfg.Query)
244		if err := ValidateRepoFilters(cfg.Repos); err != nil {
245			return nil, err
246		}
247		allRepos := len(cfg.Repos) == 1 && cfg.Repos[0] == AllReposFilter
248		if len(cfg.Repos) > 0 && !allRepos {
249			for _, repo := range cfg.Repos {
250				q.Add("repo", repo)
251			}
252		} else if len(cfg.Repos) == 0 && cfg.Owner != "" && cfg.Repo != "" {
253			q.Set("repo", cfg.Owner+"/"+cfg.Repo)
254		}
255		q.Set("types", "checkpoints")
256		if cfg.Limit > 0 {
257			q.Set("limit", strconv.Itoa(cfg.Limit))
258		}
259		if cfg.Author != "" {
260			q.Set("author", cfg.Author)
261		}
262		if cfg.Date != "" {
263			q.Set("date", cfg.Date)
264		}
265		if cfg.Branch != "" {
266			q.Set("branch", cfg.Branch)
267		}
268		if cfg.Page > 0 {
269			q.Set("page", strconv.Itoa(cfg.Page))
270		}
271		u.RawQuery = q.Encode()
272	
273		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
274		if err != nil {
275			return nil, fmt.Errorf("creating request: %w", err)
276		}
277		req.Header.Set("Authorization", "Bearer "+cfg.GitHubToken)
278		req.Header.Set("User-Agent", "entire-cli")
279	
280		resp, err := httpClient.Do(req)
281		if err != nil {
282			return nil, fmt.Errorf("calling search service: %w", err)
283		}
284		defer resp.Body.Close()
285	
286		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
